/* Keep business snapshots, chart series, period totals and exports in one scope. */
const baseKpiNumbers=importantKpis.map(k=>({...k}));
function scopedCounts(){const f=state.factory<0?1:factories[state.factory].output/428640,d=periodDays(),scale=f*d;const complaints=[3,9,7,6,4].map(v=>Math.round(v*scale)),warranty=[5,3,3,2,1].map(v=>Math.round(v*scale)),orders=Math.round(500*scale),late=Math.round(orders*(100-snapshot().delivery)/100);return {f,d,scale,complaints,warranty,orders,late,onTime:orders-late}}
function syncKpis(){const s=snapshot(),c=scopedCounts();const values=[s.quality+'%',s.satisfaction+'%','4.7 / 5',s.compliance+'%',s.recall+'%',s.legal+' open',s.delivery+'%',c.warranty.reduce((a,b)=>a+b,0)+' claims',c.complaints.reduce((a,b)=>a+b,0)+' cases',s.supplier+'%',s.defect+'%','EGP '+nfmt(s.cost*c.d)+'k',nfmt(s.downtime*c.d)+' h'];importantKpis.forEach((k,i)=>{k.value=values[i];k.status=i===3&&s.compliance<100||i===5&&s.legal>0?'Needs review':baseKpiNumbers[i].status})}
const oldKpiChart=kpiChart;kpiChart=function(k){const i=importantKpis.indexOf(k),s=snapshot(),c=scopedCounts(),trend=v=>[1.3,1.16,1.21,1.05,.95,1].map(x=>+(v*x).toFixed(2));if(i===0)return analyticsChart(k.name,'First-pass quality by product',['Tablets','Capsules','Vials'],[s.quality+.3,s.quality-.4,s.quality+.1],'%',{type:'bar',target:98});if(i===3)return analyticsChart(k.name,'Compliance checks',['GMP','Training','Records','Audit'],[s.compliance+1,s.compliance,s.compliance-1,s.compliance],'%',{type:'bar',target:100});if(i===4)return analyticsChart(k.name,'Recall trend',['P1','P2','P3','P4','P5','P6'],trend(s.recall),'%',{target:.2});if(i===7)return analyticsChart(k.name,'Claim counts',['Tablets','Vials','Capsules','Devices','Kits'],c.warranty,'claims',{type:'bar'});if(i===9)return analyticsChart(k.name,'Incoming-quality trend',['P1','P2','P3','P4','P5','P6'],trend(s.supplier),'%',{target:2});if(i===10)return analyticsChart(k.name,'Defect rates across lines',['Line 1','Line 2','Line 3'],[s.defect-.4,s.defect+.4,s.defect],'%',{type:'bar',target:2});if(i===11)return analyticsChart(k.name,'Cost contributions',['Scrap','Rework','Returns','Inspection'],[.375,.3125,.1875,.125].map(v=>+(v*s.cost*c.d).toFixed(2)),'EGP k',{type:'bar'});if(i===12)return analyticsChart(k.name,'Time lost by cause',['Changeover','Stops','Material','QA hold','Other'],[1.8/3.9,1.1/3.9,.5/3.9,.3/3.9,.2/3.9].map(v=>+(v*s.downtime*c.d).toFixed(2)),'hours',{type:'bar'});return oldKpiChart(k)};
const originalCompactBoard=businessKpiView;businessKpiView=function(){const s=snapshot(),c=scopedCounts();let html=originalCompactBoard();html=html.replaceAll('98.2%',s.quality+'%').replaceAll('92%',s.satisfaction+'%').replaceAll('96%',s.compliance+'%').replaceAll('0.1%',s.recall+'%').replaceAll('2 open',s.legal+' open').replaceAll('95.4%',s.delivery+'%').replaceAll('14 claims',importantKpis[7].value).replaceAll('29 cases',importantKpis[8].value).replaceAll('1.9%',s.supplier+'%').replaceAll('1.8%',s.defect+'%').replaceAll('EGP 32k',importantKpis[11].value).replaceAll('3.9 h',importantKpis[12].value);const wrap=document.createElement('div');wrap.innerHTML=html;const badges=wrap.querySelectorAll('.delivery-details strong');if(badges[0])badges[0].textContent=c.onTime;if(badges[1])badges[1].textContent=c.late;wrap.querySelectorAll('.complaint-map button').forEach((b,i)=>{b.querySelector('strong').textContent=c.complaints[i];b.setAttribute('onclick',`chartPoint('Consumer complaints','${['Customer service','Product','Delivery','Quality','Support'][i]}',${c.complaints[i]},'cases')`)});const sentiments=[100-s.satisfaction,14,42+(s.satisfaction-92),36];wrap.querySelectorAll('.sentiment-grid button').forEach((b,i)=>{b.querySelector('strong').textContent=sentiments[i]+'%';b.setAttribute('onclick',`chartPoint('Customer satisfaction','${['Dissatisfied','Neutral','Satisfied','Very satisfied'][i]}',${sentiments[i]},'%')`)});if(s.legal===0){const ring=wrap.querySelectorAll('.regulatory-gauges .mini-ring')[2];ring?.setAttribute('style','--fill:0%;--ring:#a0f7da')}return wrap.innerHTML};
const scopedMetricsBefore=pageMetrics;pageMetrics=function(){if(state.tab==='Supply Chain'){const s=snapshot();return [['On-time delivery',s.delivery+'%','Target 93%'],['Inventory coverage','24 days','Target 21–28 days'],['Supplier quality',nfmt(100-s.supplier)+'%','Target 98%'],['Orders at risk',state.factory<0||state.factory===2?'2':'0','Selected factory scope']]};if(state.tab==='Maintenance'&&state.factory<0){const jobs=factories.flatMap((f,fi)=>assets.map((a,i)=>({...jobFor(i,fi),cost:a.cost})));return [['Asset availability','97.8%','Target 97%'],['Open work orders',jobs.filter(j=>j.status!=='Completed').length,'Across all factories'],['Completed work orders',jobs.filter(j=>j.status==='Completed').length,'Local demo records'],['Production value at risk','EGP '+nfmt(jobs.reduce((v,j)=>v+(j.status==='Completed'?0:j.cost),0)/1000)+'k','Illustrative network impact']]};if(state.tab==='Sustainability'){const s=snapshot();return [['Energy cost per unit','EGP '+s.energy,'Target EGP 0.90'],['Water reused',s.reuse+'%','Target 65%'],['Carbon footprint',nfmt(124*scopeData().total)+' tCO₂e','Selected period'],['Waste recovery','92%','Target 90%']]};if(state.tab==='Factory Overview'){const s=snapshot(),f=state.factory<0?1:factories[state.factory].output/428640;return [['Production plan attainment',state.factory===2?'89.2%':'94.8%','Target 95%'],['Production output',nfmt(Math.round(428640*f*periodDays())),'Selected period'],['First-pass quality',s.quality+'%','Target 98%'],['On-time delivery',s.delivery+'%','Target 93%']]};return scopedMetricsBefore()};
function factoryChoice(title,tab){return `<section class="panel"><h2>${title}</h2><p>Choose the factory to inspect its assets, job records and qualified workforce.</p><div class="entity-grid">${factories.map((f,i)=>`<button class="entity" onclick="state.factory=${i};go('${tab}')"><strong>${f.name}</strong><small>${f.city}</small><div class="insight">Open factory records →</div></button>`).join('')}</div></section>`}
const priorMaintenance=maintenanceView;maintenanceView=function(){return state.factory<0?factoryChoice('Maintenance across factories','Maintenance'):priorMaintenance()};
const priorWorkforce=workforceView;workforceView=function(){return state.factory<0?factoryChoice('Workforce across factories','Workforce Mgmt'):priorWorkforce()};
const priorReportRows=reportRows;reportRows=function(kind){if(kind==='maintenance'&&state.factory<0)return factories.flatMap((f,fi)=>assets.map((a,i)=>({asset:a.id,factory:f.name,qualification:a.skill,assigned_to:people.find(p=>p.id===jobFor(i,fi).assignee)?.name||'Unassigned',status:jobFor(i,fi).status})));return priorReportRows(kind)};
function supplyChainView(){const s=snapshot();return `<div class="business-strip"><strong>Supply chain outlook</strong><span>Balance material coverage, supplier performance and customer commitments.</span></div><div class="analytics-grid"><section class="panel"><h2>Material readiness</h2><table><tr><th>Material</th><th>Coverage</th><th>State</th></tr><tr><td>API input</td><td>24 days</td><td class="positive">Available</td></tr><tr><td>Blister film</td><td>18 days</td><td class="warning">Reorder review</td></tr><tr><td>Vial components</td><td>27 days</td><td class="positive">Available</td></tr></table><div class="actions">${opButton('Reorder decision','supplyDecision()')}</div></section><section class="panel"><h2>Customer commitments</h2><table><tr><th>Order</th><th>Product</th><th>Delivery impact</th></tr><tr><td>SO-3041</td><td>Capsules</td><td class="warning">Packaging recovery required</td></tr><tr><td>SO-3042</td><td>Tablets</td><td class="positive">On track</td></tr><tr><td>SO-3043</td><td>Cold-chain vials</td><td class="positive">2–8°C sample window</td></tr></table><div class="actions">${opButton('Packaging recovery','openAction(0)')}${opButton('Export current scope',"reportCenter('production')")}</div></section>${analyticsChart('On-time delivery','Customer service performance',scopeData().labels,[s.delivery-2,s.delivery-1,s.delivery-.5,s.delivery-1.2,s.delivery+.2,s.delivery],'%',{target:93})}${analyticsChart('Supplier quality','Accepted incoming units',['API','Packaging','Components'],[98.8,97.9,99.1],'%',{type:'bar',target:98})}</div>`}
function supplyDecision(){openModal('Material replenishment decision','<p>Blister film coverage is 18 days against a 21-day minimum target.</p><p>Business impact: replenishment is needed before the next planned packaging campaign.</p><div class="actions">'+opButton('Record demo review',"eventLog('Blister film reorder reviewed','Supply Chain');openModal('Review recorded','The demo planning review was recorded. No purchase order was transmitted.')")+'</div>')}
const scopedBusinessBefore=businessSection;businessSection=function(){if(state.tab==='Supply Chain')return supplyChainView();return scopedBusinessBefore()};
const documentsBeforeScope=documentRecords;documentRecords=function(){return [...documentsBeforeScope(),...assets.slice(1).map(a=>({id:'MAN-'+a.id.replaceAll('-',''),area:'Maintenance',title:a.id+' '+a.name+' manual',version:'1.0',sections:[['Asset identity',a.id+' · '+a.name+' · '+a.area],['Illustrative condition limits',a.reading+'. '+a.target+'. Use approved manufacturer limits in production.'],['Maintenance eligibility',a.skill+' qualification is required. Expired qualifications are excluded from demo assignment.'],['Demo note','This sample manual demonstrates document access. It is not an approved operating or servicing instruction.']]}))]};
const qualityBeforeScope=quality;quality=function(){return state.factory<0?factoryChoice('Choose a factory for CIP & PAT monitoring','Quality'):qualityBeforeScope()};
advanceCip=function(){cipPhase=cipPhase===4?0:cipPhase+1;saved.cipCycles??={};saved.cipCycles[factoryIndex()]=cipPhase;eventLog('CIP-01 demo phase: '+cipSteps[cipPhase],'Quality');render()};
sustainabilityCharts=function(){const s=scopeData(),snap=snapshot(),mul=arr=>arr.map(v=>+(v*s.total).toFixed(2)),focus=sustainabilityFocus,charts=[['Energy',analyticsChart('Energy consumption','Operating-period profile',s.labels,mul([22,29,35,32,26,24]),'MWh')],['Energy',analyticsChart('Energy cost per unit','Efficiency against budget',s.labels,[1.14,1.1,1.06,1.03,1.01,1].map(v=>+(v*snap.energy).toFixed(2)),'EGP/unit',{target:.9})],['Water',analyticsChart('Water withdrawal','Demand across production areas',['Process','CIP','Cooling','Facility'],mul([1080,680,540,340]),'m³',{type:'bar'})],['Water',analyticsChart('Water reuse','Water demand recovered',s.labels,[-10,-8,-5,-3,-1,0].map(v=>snap.reuse+v),'%',{target:65})],['Emissions',analyticsChart('Carbon emissions','Operating-period emissions profile',s.labels,mul([26,23,22,20,18,15]),'tCO₂e')],['Emissions',compositionChart('Emissions by source','Largest contributors',['Electricity','Fuel','Purchased steam'],mul([74,31,19]),'tCO₂e')],['Waste',compositionChart('Waste destination','Recovery pathways',['Recycled','Recovered','Disposed'],mul([11.7,4.86,1.44]),'tonnes')],['Waste',analyticsChart('Waste recovery','Diversion progress',s.labels,[84,86,88,89,91,92],'%',{target:90})]];return `<div class="business-strip"><strong>Sustainability outlook</strong><span>${snap.energy>.9?'Energy cost per unit is above target; prioritize efficiency review.':'Energy cost per unit is within target.'} ${snap.reuse<65?'Water reuse needs attention.':'Water reuse is above target.'}</span></div><div class="analytics-toolbar"><div><h2>Environmental performance</h2><small>${s.p} · ${scopeName()}</small></div><div class="segmented">${['All resources','Energy','Water','Emissions','Waste'].map(t=>`<button class="${focus===t?'active':''}" onclick="sustainabilityFocus='${t}';render()">${t}</button>`).join('')}</div></div><div class="analytics-grid">${charts.filter(x=>focus==='All resources'||x[0]===focus).map(x=>x[1]).join('')}</div>`};
const renderBeforeScope=render;render=function(){syncKpis();cipPhase=saved.cipCycles?.[factoryIndex()]??1;renderBeforeScope();if(state.tab==='Business KPIs'){const note=$('.compact-board-note>span');if(note)note.textContent=scopeName()+' · '+$('#period').value+' · Demo data · Select a reading for details.'}};
render();
